<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { useRouter } from "vue-router";
import { getRepositoryAssetDetails, isTauriRuntime, listRepositoryAssets, saveRepositoryAsset, scanGitRepositories, type RepositoryAsset, type RepositoryAssetDetails, type RepositoryAssetUpdate } from "../services/backend";

const router=useRouter(); const assets=ref<RepositoryAsset[]>([]); const selected=ref<RepositoryAsset|null>(null); const details=ref<RepositoryAssetDetails>({conversations:[],commits:[]});
const query=ref(""); const health=ref("全部状态"); const changes=ref("全部工作区"); const loading=ref(false); const editing=ref(false); const message=ref(""); const error=ref("");
const form=reactive<RepositoryAssetUpdate>({path:"",category:"待确认",purpose:"",technologyStack:"",mainModules:"",installCommand:"",startCommand:"",testCommand:"",buildCommand:"",commandSource:""});
const filtered=computed(()=>{const keyword=query.value.trim().toLowerCase();return assets.value.filter(item=>{if(health.value!=="全部状态"&&item.healthLevel!==health.value)return false;if(changes.value==="有未提交修改"&&!item.hasUncommittedChanges)return false;if(changes.value==="工作区干净"&&item.hasUncommittedChanges)return false;return !keyword||[item.name,item.path,item.purpose,item.technologyStack,item.category].some(value=>value.toLowerCase().includes(keyword));});});
const dirtyCount=computed(()=>assets.value.filter(item=>item.hasUncommittedChanges).length); const confirmedCount=computed(()=>assets.value.filter(item=>item.manuallyConfirmed).length); const failedCount=computed(()=>assets.value.filter(item=>item.healthLevel==="失败").length);
function healthClass(value:string){return value==="健康"?"healthy":value==="警告"?"warning":value==="失败"?"failed":"unknown";}
function fillForm(item:RepositoryAsset){Object.assign(form,{path:item.path,category:item.category,purpose:item.purpose,technologyStack:item.technologyStack,mainModules:item.mainModules,installCommand:item.installCommand,startCommand:item.startCommand,testCommand:item.testCommand,buildCommand:item.buildCommand,commandSource:item.commandSource});}
async function load(){if(!isTauriRuntime())return;loading.value=true;error.value="";try{assets.value=await listRepositoryAssets();}catch(cause){error.value=String(cause);}finally{loading.value=false;}}
async function openAsset(item:RepositoryAsset){selected.value=item;editing.value=false;fillForm(item);error.value="";try{details.value=await getRepositoryAssetDetails(item.path);}catch(cause){error.value=String(cause);details.value={conversations:[],commits:[]};}}
async function scan(){loading.value=true;error.value="";message.value="";try{const result=await scanGitRepositories();message.value=`已扫描 ${result.repositoriesFound} 个仓库，${result.errors} 个项目需要人工确认。`;await load();}catch(cause){error.value=String(cause);loading.value=false;}}
async function save(){loading.value=true;error.value="";try{await saveRepositoryAsset({...form});message.value="人工修正已保存，后续扫描不会覆盖这些说明。";await load();const refreshed=assets.value.find(item=>item.path===form.path);if(refreshed)await openAsset(refreshed);editing.value=false;}catch(cause){error.value=String(cause);}finally{loading.value=false;}}
function exportText(format:"markdown"|"csv"){if(format==="csv"){const quote=(value:string|number|boolean)=>`"${String(value).replaceAll('"','""')}"`;return [["项目","路径","分类","用途","技术栈","分支","健康状态","未提交修改","Codex任务","提交记录"].map(quote).join(","),...filtered.value.map(item=>[item.name,item.path,item.category,item.purpose,item.technologyStack,item.defaultBranch,item.healthLevel,item.hasUncommittedChanges?"是":"否",item.conversationCount,item.commitCount].map(quote).join(","))].join("\n");}return ["# 项目资产清单","",`共 ${filtered.value.length} 个项目`,"",...filtered.value.flatMap(item=>[`## ${item.name}`,`- 路径：${item.path}`,`- 分类：${item.category}`,`- 用途：${item.purpose||"待确认"}`,`- 技术栈：${item.technologyStack||"待确认"}`,`- 健康：${item.healthLevel}${item.hasUncommittedChanges?"（有未提交修改）":""}`,""])].join("\n");}
async function copyExport(format:"markdown"|"csv"){await navigator.clipboard.writeText(exportText(format));message.value=`${format==="csv"?"CSV":"Markdown"} 清单已复制，可直接保存为文件。`;}
onMounted(load);
</script>

<template><div class="view projects-view"><header class="page-header"><div><h1>项目资产</h1><p>统一查看本机 Git 仓库、关联 Codex 任务、健康状态和运行说明</p></div><div><button class="button secondary" @click="copyExport('csv')">导出 CSV</button><button class="button secondary" @click="copyExport('markdown')">导出 Markdown</button><button class="button primary" :disabled="loading" @click="scan">{{ loading?'扫描中…':'↻ 重新扫描' }}</button></div></header>
<div v-if="error||message" class="scan-message" :class="{error:Boolean(error)}">{{ error||message }}</div><section class="asset-metrics"><article class="panel"><small>项目总数</small><b>{{ assets.length }}</b><span>默认扫描 F:\ 与文档目录</span></article><article class="panel warning"><small>有未提交修改</small><b>{{ dirtyCount }}</b><span>仅提示，不等同于项目故障</span></article><article class="panel"><small>人工确认</small><b>{{ confirmedCount }}</b><span>人工说明优先保留</span></article><article class="panel failed"><small>扫描失败</small><b>{{ failedCount }}</b><span>需要查看失败原因</span></article></section>
<section class="panel asset-workspace"><div class="asset-toolbar"><label>⌕<input v-model="query" placeholder="搜索项目、路径、用途或技术栈"></label><select v-model="health"><option>全部状态</option><option>健康</option><option>警告</option><option>失败</option><option>未验证</option></select><select v-model="changes"><option>全部工作区</option><option>有未提交修改</option><option>工作区干净</option></select><span>{{ filtered.length }} / {{ assets.length }}</span></div><div class="asset-table-wrap"><table class="asset-table"><thead><tr><th>项目</th><th>用途与分类</th><th>技术栈</th><th>关联数据</th><th>健康</th><th>工作区</th><th></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.path" @click="openAsset(item)"><td><b>{{ item.name }}</b><small>{{ item.path }}</small></td><td><span>{{ item.category }}</span><small>{{ item.purpose||'AI 推断待确认' }}</small></td><td>{{ item.technologyStack||'待确认' }}</td><td><span>{{ item.conversationCount }} 个 Codex 任务</span><small>{{ item.commitCount }} 条最近提交</small></td><td><i class="health-pill" :class="healthClass(item.healthLevel)">{{ item.healthLevel }}</i></td><td><i v-if="item.hasUncommittedChanges" class="dirty-pill">有修改</i><span v-else class="clean-text">干净</span></td><td><button class="text-button" @click.stop="openAsset(item)">查看 →</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><b>没有符合条件的项目</b><p>请调整筛选条件或重新扫描。</p></div></div></section>
<div v-if="selected" class="activity-backdrop" @click.self="selected=null"><aside class="asset-drawer panel"><header><div><small>PROJECT ASSET</small><h2>{{ selected.name }}</h2><p>{{ selected.path }}</p></div><button class="icon-button" @click="selected=null">×</button></header><div class="asset-status-strip"><span class="health-pill" :class="healthClass(selected.healthLevel)">{{ selected.healthLevel }}</span><span>{{ selected.defaultBranch||'无分支' }}</span><span>{{ selected.hasUncommittedChanges?'有未提交修改':'工作区干净' }}</span><span>{{ selected.manuallyConfirmed?'人工已确认':'AI 推断待确认' }}</span></div>
<template v-if="!editing"><section class="asset-overview"><h3>项目说明</h3><dl><div><dt>分类</dt><dd>{{ selected.category }}</dd></div><div><dt>用途</dt><dd>{{ selected.purpose||'尚未确认项目用途' }}</dd></div><div><dt>技术栈</dt><dd>{{ selected.technologyStack||'尚未确认技术栈' }}</dd></div><div><dt>主要模块</dt><dd>{{ selected.mainModules||'尚未整理主要模块' }}</dd></div></dl><button class="button primary" @click="editing=true">编辑并人工确认</button></section><section class="asset-commands"><h3>运行与验证命令</h3><div v-for="[label,value] in [['安装',selected.installCommand],['启动',selected.startCommand],['测试',selected.testCommand],['构建',selected.buildCommand]]" :key="label"><span>{{ label }}</span><code>{{ value||'待确认，不自动执行' }}</code></div><small>来源：{{ selected.commandSource||'尚未确认' }}。工作台不会从 README 任意执行命令。</small></section></template>
<form v-else class="asset-form" @submit.prevent="save"><label>项目分类<input v-model="form.category" placeholder="例如：业务系统 / 工具 / 视频工程"></label><label>项目用途<textarea v-model="form.purpose" rows="3" placeholder="一句话说明这个项目解决什么问题"></textarea></label><label>技术栈<input v-model="form.technologyStack" placeholder="例如：Vue 3 / Vite / Element Plus"></label><label>主要模块<textarea v-model="form.mainModules" rows="2" placeholder="用逗号分隔主要功能模块"></textarea></label><div class="form-grid"><label>安装命令<input v-model="form.installCommand"></label><label>启动命令<input v-model="form.startCommand"></label><label>测试命令<input v-model="form.testCommand"></label><label>构建命令<input v-model="form.buildCommand"></label></div><label>命令来源<input v-model="form.commandSource" placeholder="例如：package.json scripts（已核对）"></label><footer><button type="button" class="button secondary" @click="editing=false">取消</button><button class="button primary" :disabled="loading">保存人工结果</button></footer></form>
<section class="asset-related"><div><h3>关联 Codex 任务</h3><button v-for="item in details.conversations" :key="item.id" @click="router.push(`/tokens?conversation=${item.id}`)"><span><b>{{ item.title }}</b><small>{{ item.updatedAt.slice(0,10) }} · {{ item.archived?'归档任务':'普通任务' }}</small></span><em>查看 →</em></button><p v-if="!details.conversations.length">暂无直接关联任务。</p></div><div><h3>最近 Git 提交</h3><article v-for="item in details.commits" :key="item.hash"><code>{{ item.hash.slice(0,7) }}</code><span><b>{{ item.subject }}</b><small>{{ item.committedAt.slice(0,10) }}</small></span></article><p v-if="!details.commits.length">暂无可读取提交。</p></div></section></aside></div></div></template>

<style scoped>
.asset-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:12px}.asset-metrics article{padding:15px 17px;min-height:92px}.asset-metrics small,.asset-metrics span{color:var(--muted)}.asset-metrics b{display:block;font-size:27px;margin:7px 0}.asset-metrics span{font-size:9px}.asset-metrics .warning b{color:var(--warning)}.asset-metrics .failed b{color:var(--danger)}.asset-workspace{overflow:hidden}.asset-toolbar{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:9px;padding:0 14px}.asset-toolbar label{flex:1;max-width:410px;height:35px;border:1px solid var(--line);border-radius:7px;display:flex;align-items:center;gap:8px;padding:0 10px;color:var(--muted)}.asset-toolbar input{flex:1;border:0;outline:0;background:transparent}.asset-toolbar select{height:35px;border:1px solid var(--line);border-radius:7px;background:var(--surface-2);padding:0 10px}.asset-toolbar>span{margin-left:auto;color:var(--muted)}.asset-table-wrap{max-height:590px;overflow:auto}.asset-table{width:100%;border-collapse:collapse}.asset-table th{text-align:left;color:var(--muted);font-size:9px;background:var(--surface-2);position:sticky;top:0;z-index:2}.asset-table th,.asset-table td{padding:11px 12px;border-bottom:1px solid var(--line)}.asset-table tbody tr{cursor:pointer}.asset-table tbody tr:hover{background:var(--primary-soft)}.asset-table td b,.asset-table td small{display:block;max-width:240px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.asset-table td small{color:var(--muted);font-size:9px;margin-top:5px}.health-pill,.dirty-pill{display:inline-flex;padding:5px 8px;border-radius:12px;font-style:normal;font-size:9px}.health-pill.healthy{color:var(--success);background:color-mix(in srgb,var(--success) 12%,transparent)}.health-pill.warning,.dirty-pill{color:var(--warning);background:color-mix(in srgb,var(--warning) 12%,transparent)}.health-pill.failed{color:var(--danger);background:color-mix(in srgb,var(--danger) 12%,transparent)}.health-pill.unknown{color:var(--muted);background:var(--surface-2)}.clean-text{color:var(--success);font-size:10px}.asset-drawer{width:720px;height:100%;margin-left:auto;border-radius:0;overflow:auto;padding-bottom:30px}.asset-drawer>header{padding:20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.asset-drawer h2{margin:4px 0}.asset-drawer header p,.asset-drawer header small{margin:0;color:var(--muted)}.asset-status-strip{display:flex;gap:8px;align-items:center;padding:12px 20px;background:var(--surface-2);border-bottom:1px solid var(--line)}.asset-status-strip>span:not(.health-pill){padding:5px 8px;border:1px solid var(--line);border-radius:12px;font-size:9px;color:var(--muted)}.asset-overview,.asset-commands,.asset-form{padding:18px 20px;border-bottom:1px solid var(--line)}.asset-drawer h3{margin:0 0 13px}.asset-overview dl{display:grid;grid-template-columns:1fr 1fr;gap:9px}.asset-overview dl div{padding:11px;background:var(--surface-2);border-radius:7px}.asset-overview dt{color:var(--muted);font-size:9px}.asset-overview dd{margin:6px 0 0;line-height:1.5}.asset-commands>div{display:grid;grid-template-columns:55px 1fr;align-items:center;margin-bottom:7px}.asset-commands code{padding:8px;background:var(--surface-2);border-radius:6px}.asset-commands small{color:var(--muted)}.asset-form label{display:flex;flex-direction:column;gap:6px;color:var(--muted);font-size:10px;margin-bottom:11px}.asset-form input,.asset-form textarea{border:1px solid var(--line);border-radius:7px;background:var(--surface-2);padding:9px;outline:0}.asset-form input:focus,.asset-form textarea:focus{border-color:var(--primary)}.asset-form footer{display:flex;justify-content:flex-end;gap:8px}.asset-related{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:18px 20px}.asset-related>div{min-width:0}.asset-related button,.asset-related article{width:100%;border:1px solid var(--line);border-radius:7px;background:var(--surface-2);color:inherit;padding:9px;margin-bottom:7px;display:flex;align-items:center;gap:9px;text-align:left}.asset-related button span,.asset-related article span{min-width:0;flex:1;display:flex;flex-direction:column;gap:4px}.asset-related b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.asset-related small,.asset-related em,.asset-related p{color:var(--muted);font-size:9px}.asset-related em{font-style:normal}.asset-related article code{color:var(--primary)}
</style>
